"""Static entry points and documented data semantics for local format conversion."""
import html

DATA_TOOLS = [
    ('yaml-to-json', 'YAML ↔ JSON', 'Data formats', 'Convert YAML 1.2 to JSON or JSON to YAML. Check types, duplicate keys and aliases locally.', 'code'),
    ('csv-to-json', 'CSV ↔ JSON', 'Data formats', 'Convert CSV to JSON or JSON to CSV. Choose headers, delimiters and explicit type handling.', 'code'),
]
YAML_SAMPLE = 'app: ParseCove\nready: true\nports:\n  - 3000\n  - 8080\nowner:\n  name: Ada\n  id: "001"'
CSV_SAMPLE = 'id,name,active\n001,Ada,true\n002,"Lin, Mei",false'


def workbench(kind, segmented, copy):
    yaml = kind == 'yaml'
    first = 'YAML' if yaml else 'CSV'
    sample = YAML_SAMPLE if yaml else CSV_SAMPLE
    body = '<section class="workbench data-workbench"><div class="bench-toolbar">' + segmented([('forward', first+' to JSON'), ('reverse', 'JSON to '+first)], 'data-modes') + '<span class="quiet">Local files & pasted text</span></div><div class="data-options">'
    body += '<div><label for="data-indent" id="data-indent-label">JSON indentation</label><select id="data-indent"><option value="2">2 spaces</option><option value="4">4 spaces</option><option value="0">Compact</option></select></div>'
    if not yaml:
        body += '''<div><label for="data-delimiter">Delimiter</label><select id="data-delimiter"><option value="auto">Auto (CSV input)</option><option value=",">Comma (,)</option><option value="tab">Tab</option><option value=";">Semicolon (;)</option><option value="|">Pipe (|)</option></select></div><div class="data-reverse" hidden><label for="data-newline">CSV line endings</label><select id="data-newline"><option value="crlf">CRLF</option><option value="lf">LF</option></select></div><div class="check-field"><label><input id="data-headers" type="checkbox" checked> <span id="data-headers-label">First row contains headers</span></label></div><div class="data-forward check-field"><label><input id="data-infer" type="checkbox"> Infer JSON types</label></div><div class="data-forward check-field"><label><input id="data-skip" type="checkbox"> Skip empty rows</label></div><div class="data-reverse check-field" hidden><label><input id="data-nested" type="checkbox"> Serialize nested values as JSON</label></div><div class="data-reverse check-field" hidden><label><input id="data-protect" type="checkbox" checked> Protect spreadsheet formulas</label></div>'''
    body += '</div><div class="bench-body"><div class="input-panel"><label for="data-input" id="data-input-label">'+first+' input</label><textarea id="data-input" class="mono data-editor" rows="12" spellcheck="false">'+html.escape(sample)+'</textarea>'
    body += '<p class="hint">Up to 1 million UTF-16 code units. UTF-8 files up to 2 MB. Nothing is uploaded.</p><div class="data-file"><label for="data-file">Open a local file</label><input id="data-file" type="file" accept="'+('.yaml,.yml,.json,.txt' if yaml else '.csv,.tsv,.json,.txt')+'"><p id="data-file-note" class="hint" role="status"></p></div><div class="actions"><button class="button primary" id="data-convert">Convert to JSON</button><button class="button ghost" id="data-clear">Clear</button></div><p class="mono-label example-label">TRY A COMPLETE EXAMPLE</p><div class="example-buttons">'
    examples = [('basic', 'Nested YAML'), ('types', 'YAML 1.2 types'), ('aliases', 'Shared values'), ('json', 'JSON input')] if yaml else [('basic', 'IDs & headers'), ('quoted', 'Quoted fields'), ('tab', 'Tab-separated'), ('json', 'JSON records')]
    body += ''.join('<button class="button small" data-data-example="'+key+'">'+label+'</button>' for key, label in examples)
    body += '</div><p class="error" id="data-error" role="alert" hidden></p></div><div class="result-panel"><div class="result-head"><label class="mono-label" id="data-output-label" for="data-output">JSON RESULT</label>'+copy('data-copy')+'</div><textarea id="data-output" class="mono data-editor" rows="16" readonly></textarea><span id="data-copy" hidden></span><p class="result-sub" id="data-status" role="status">Choose an example or convert your input.</p><div class="actions"><button class="button" id="data-download" disabled>Download JSON</button></div><p class="hint">Editing input or options clears the previous result. Convert again to apply changes.</p></div></div></section>'
    return body


def data_tool_pages(tool_head, segmented, copy, docs, extra_section, ad_slot, related):
    yaml = tool_head('yaml-to-json', 'DATA FORMATS', 'YAML to JSON converter', 'Convert YAML 1.2 to JSON, or switch to JSON to YAML. Paste a document or open a local UTF-8 file, inspect the result and download it. All conversion runs in your browser.')
    yaml += workbench('yaml', segmented, copy) + ad_slot('tool_primary')
    yaml += docs('How to convert YAML to JSON', 'Paste one YAML document, select the JSON indentation and choose Convert. Mappings become objects and sequences become arrays. For the reverse direction, select JSON to YAML and provide strict JSON. Switching modes uses the last successful result as the next input.', 'YAML 1.2 core types ↔ JSON values', [
        ('Which YAML version and types are supported?', 'This converter uses the YAML 1.2 core schema. true and false become booleans; yes, no, on and off remain strings. Dates such as 2026-11-27 remain strings. JSON supports strings, finite numbers, booleans, null, arrays and objects with string keys.'),
        ('Are comments and formatting preserved?', 'No. Conversion preserves supported data values, not comments, key order in every case, quoting style or layout. JSON has no comments. Reverse conversion quotes string values so text such as "true" and "001" keeps its string type.'),
        ('Can I convert anchors, aliases or multiple documents?', 'Bounded, noncyclic aliases can be expanded into repeated JSON values. Cycles, excessive alias expansion, YAML merge keys (<<), custom tags, YAML 1.1 directives and multiple documents are rejected. Expand merges and split document streams before converting.'),
        ('Why are a duplicate key or numeric mapping key rejected?', 'Duplicate keys can hide a value that another parser would overwrite. They are rejected in both YAML and JSON. JSON object keys are strings, so quote numeric YAML keys. Complex mapping keys have no supported JSON representation.'),
        ('What happens to large integers and decimal numbers?', 'Integers outside −9,007,199,254,740,991 through 9,007,199,254,740,991 are rejected; put exact IDs and larger integers in quotes. Decimal values use standard JavaScript number precision. Non-finite values such as .nan and .inf are rejected. Negative zero may normalize to zero in JSON.'),
        ('What are the input and file limits?', 'Paste up to 1,000,000 UTF-16 code units or read a UTF-8 file up to 2,000,000 bytes, subject to the same text limit. Documents are limited to 80 nesting levels and 50,000 values and fields; output is limited to 3,000,000 characters. An initial UTF-8 BOM is treated as an encoding marker. Local .yaml, .yml, .json and .txt files are accepted; .yml and .yaml are alternate extensions, not different schemas. Empty YAML becomes null; empty JSON is invalid.'),
    ], '<a href="https://yaml.org/spec/1.2.2/">YAML 1.2.2 specification</a> · <a href="https://eemeli.org/yaml/">YAML parser documentation</a> · <a href="https://www.rfc-editor.org/rfc/rfc8259">JSON: RFC 8259</a>')
    yaml += extra_section('yaml-types', 'Check types before sharing configuration', 'The same-looking input can represent a different type. Quote values when their exact text matters.', '''<div class="table-wrap"><table><thead><tr><th>YAML input</th><th>JSON value</th><th>Reason</th></tr></thead><tbody><tr><td><code>ready: true</code></td><td><code>{"ready":true}</code></td><td>Boolean</td></tr><tr><td><code>answer: yes</code></td><td><code>{"answer":"yes"}</code></td><td>YAML 1.2 core string</td></tr><tr><td><code>id: "001"</code></td><td><code>{"id":"001"}</code></td><td>Quoted identifier</td></tr><tr><td><code>date: 2026-11-27</code></td><td><code>{"date":"2026-11-27"}</code></td><td>Core schema does not resolve timestamps</td></tr><tr><td><code>items: [red, blue]</code></td><td><code>{"items":["red","blue"]}</code></td><td>Sequence to array</td></tr></tbody></table></div><p>Conversion checks supported syntax and types; it does not validate a deployment configuration against an application-specific schema. For a worked comparison of types, comments and conversion losses, read <a href="/guides/yaml-vs-json/">YAML vs JSON</a>. For tabular records, use <a href="/csv-to-json/">CSV ↔ JSON</a>. For a JSON string containing escaped newlines or quotes, use <a href="/json-unescape/">JSON unescape</a> before converting the resulting document.</p>''')
    yaml += ad_slot('tool_secondary') + related('yaml-to-json')

    csv = tool_head('csv-to-json', 'DATA FORMATS', 'CSV to JSON converter', 'Convert CSV to JSON or JSON to CSV with explicit headers, delimiters and type options. Read a local UTF-8 file, inspect the result, then copy or download it in your browser.')
    csv += workbench('csv', segmented, copy) + ad_slot('tool_primary')
    csv += docs('How to convert CSV to JSON', 'Paste CSV or open a local file. Choose a delimiter, decide whether the first row contains headers and select Convert. Leave type inference off to retain every field as a string. Switch modes to turn an array of JSON objects or arrays into CSV.', 'CSV records ↔ JSON objects or array rows', [
        ('Will identifiers keep their leading zeros?', 'Yes. CSV input defaults to strings: 001 stays "001", an empty cell stays "", and large IDs remain text. Optional type inference recognizes exact true, false, null and JSON-number syntax. Leading-zero numbers and values with surrounding spaces remain strings. Unsafe or non-finite numeric values also remain strings; decimals use JavaScript number precision.'),
        ('How do headers and uneven rows work?', 'With headers enabled, the first record supplies nonempty, unique, case-sensitive object keys. Duplicate or blank headers are rejected. Headerless input produces arrays. All rows must have the same number of fields; missing and extra fields produce an error. Header spaces and cell whitespace are preserved. Skip empty rows removes records whose cells are all empty, not whitespace-only records.'),
        ('Which delimiters and quoted fields work?', 'Auto detection considers comma, tab, semicolon and pipe. If detection is inconclusive, comma is used and the result explains that choice. Choose the delimiter explicitly for ambiguous files. Quoted fields may contain delimiters and newlines; escape a quote by doubling it. Bare quotes and malformed quoted fields are rejected. One final record terminator does not create an extra row.'),
        ('What JSON shape can be exported as CSV?', 'Use an array of objects or an array of equal-length arrays. Object headers use the union of keys in first-seen order. Missing keys and null become empty cells; CSV cannot preserve that distinction from an empty string. Nested objects and arrays are rejected unless Serialize nested values as JSON is enabled. Array rows do not receive generated headers. An empty array downloads as an empty file.'),
        ('What does spreadsheet formula protection change?', 'In JSON to CSV mode, protection is on by default. String cells starting with =, +, -, @, tab or carriage return receive a leading apostrophe, including headers. The status shows how many changed. Actual numeric negative values remain numeric text. Turn protection off when exact original string values are required. CSV quoting alone does not prevent spreadsheet formulas; different spreadsheet import settings can behave differently.'),
        ('What are the limits and line endings?', 'Input is limited to 1,000,000 UTF-16 code units; UTF-8 files to 2 MB; tables to 10,000 data records and 200 columns. JSON documents also have an 80-level and 50,000-value/field limit. Output is limited to 3,000,000 characters. CSV output quotes every cell and offers CRLF or LF record endings. An initial UTF-8 BOM is removed. Files and conversion input stay in browser memory.'),
    ], '<a href="https://www.rfc-editor.org/rfc/rfc4180">CSV conventions: RFC 4180</a> · <a href="https://www.papaparse.com/docs">Papa Parse documentation</a> · <a href="https://owasp.org/www-community/attacks/CSV_Injection">OWASP: spreadsheet formula injection</a>')
    csv += extra_section('csv-data-types', 'Keep a record’s meaning explicit', 'CSV has fields, but no built-in number, boolean or null types. Select the interpretation that fits your destination.', '''<div class="table-wrap"><table><thead><tr><th>CSV field</th><th>Default JSON</th><th>With type inference</th></tr></thead><tbody><tr><td><code>001</code></td><td><code>"001"</code></td><td><code>"001"</code></td></tr><tr><td><code>42</code></td><td><code>"42"</code></td><td><code>42</code></td></tr><tr><td><code>true</code></td><td><code>"true"</code></td><td><code>true</code></td></tr><tr><td><code>null</code></td><td><code>"null"</code></td><td><code>null</code></td></tr><tr><td>Empty cell</td><td><code>""</code></td><td><code>""</code></td></tr><tr><td><code>9007199254740993</code></td><td>Exact string</td><td>Exact string; unsafe as a number</td></tr></tbody></table></div><p>A comma inside a name belongs inside double quotes: <code>002,"Lin, Mei",false</code> has three fields. A quote inside a quoted field is doubled. This is structural conversion, not automatic repair of broken exports. For configuration documents, use <a href="/yaml-to-json/">YAML ↔ JSON</a>. To decode a string containing a JSON document, use <a href="/json-unescape/">JSON unescape</a>.</p>''')
    csv += extra_section('nested-json-cells', 'Nested JSON: a string cell or an expanded table?', 'Choose the intended shape before exporting. Preserving an object inside one cell is a different transformation from expanding its fields into columns.', '<p>For a complete example, choose JSON to CSV, paste the input below, enable Serialize nested values as JSON and select Convert to CSV. The id remains a string. The customer object and tags array are each stored as JSON text in one CSV cell.</p><pre><code>'+html.escape('[{"id":"001","customer":{"name":"Ada"},"tags":["red","blue"]}]')+'</code></pre><p>With object headers, comma delimiter and the default CRLF record ending, the result is:</p><pre><code>'+html.escape('"id","customer","tags"\n"001","{""name"":""Ada""}","[""red"",""blue""]"')+'</code></pre><p>The doubled quotes belong to CSV escaping. Parsing this CSV with string values produces a customer string containing <code>{&quot;name&quot;:&quot;Ada&quot;}</code>, not an automatically restored object. See <a href="/guides/json-double-encoding/">JSON strings and encoding layers</a> for how representations differ.</p><div class="table-wrap"><table><thead><tr><th>Goal</th><th>Result shape</th><th>Current tool</th></tr></thead><tbody><tr><td>Preserve nested values</td><td>One row; customer and tags each occupy one cell</td><td>Supported with nested serialization enabled</td></tr><tr><td>Expand object fields</td><td>A customer.name column containing Ada</td><td>Requires a separate flattening transformation</td></tr><tr><td>Expand array items</td><td>Two rows, one per tag, repeating the parent id</td><td>Requires a defined array-expansion policy</td></tr></tbody></table></div><p>Arrays can multiply row counts; missing fields, empty arrays and identical path names also need explicit rules. This converter does not guess those rules or automatically flatten objects. Files are read one at a time, with the limits above. JSONL output and multi-file merging are outside the current format options.</p>')
    csv += ad_slot('tool_secondary') + related('csv-to-json')
    note = '<noscript><p class="hint">JavaScript enables conversion, file reading, copy and downloads. Examples, type rules and reference sections remain readable.</p></noscript>'
    return [
        ('yaml-to-json', 'YAML to JSON Converter & JSON to YAML', 'Convert YAML 1.2 to JSON or JSON to YAML locally. Open UTF-8 files, check duplicate keys and types, then copy or download the result.', yaml+note),
        ('csv-to-json', 'CSV to JSON Converter & JSON to CSV', 'Convert CSV to JSON or JSON to CSV in your browser. Choose headers, delimiters and type inference; open local files and download the result.', csv+note),
    ]
